type SearchPage struct{ page playwright.Page }

func NewSearchPage(p playwright.Page) *SearchPage { return &SearchPage{page: p} }

func (s *SearchPage) Search(text string) error {
    if err := s.page.Locator("#q").Fill(text); err != nil {
        return err
    }
    return s.page.Locator("#q").Press("Enter")
}
